@madolson I don't know if you remember, I once found that `strlen` was faster than `sdslen`.
I just wrote another test code, and the result is the same.

```c
sds x = sdsnew("foo"), y;
size_t len;
unsigned long long start = usec();
for (size_t i = 0; i < 10000000; i++) {
        len += sdslen(x);
}
printf("Done. usec=%lld\n", usec()-start);
printf("%zu\n", len);

# Output
Done. usec=11711
```

```c
sds x = sdsnew("foo"), y;
size_t len;
unsigned long long start = usec();
for (size_t i = 0; i < 10000000; i++) {
    len += strlen(x);
}
printf("%zu\n", len);
printf("Done. usec=%lld\n", usec()-start);
return 1;

# Output
Done. usec=232
```

